import { existsSync } from 'node:fs';

const RULES = [
  { pattern: /rm\s+-rf/, block: true, reason: '危險操作：遞迴刪除' },
  { pattern: /git\s+push.*--force/, block: true, reason: 'force push 不允許' },
];

const on = {};
on.PreToolUse = async (input) => {
  if (input.tool_name !== 'Bash') return { decision: 'allow' };
  const cmd = input.tool_input?.command || '';
  for (const rule of RULES) {
    if (rule.pattern.test(cmd)) {
      return { decision: 'block', reason: rule.reason };
    }
  }
  return { decision: 'allow' };
};
export { on };

